USE db_predicciones;
CREATE TABLE IF NOT EXISTS forecast_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, products_scanned INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expiry_risks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, run_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, product_name VARCHAR(180) NOT NULL, batch_id BIGINT UNSIGNED NOT NULL, lot_number VARCHAR(100) NOT NULL, expiry_date DATE NOT NULL, days_remaining INT NOT NULL, quantity INT NOT NULL, avg_daily_demand DECIMAL(12,3) NOT NULL, estimated_leftover INT NOT NULL, risk_level ENUM('low','medium','high') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_run (run_id), FOREIGN KEY (run_id) REFERENCES forecast_runs(id)) ENGINE=InnoDB;
